default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('\\*\NETLOGON', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('\\*\NETLOGON') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq 'RequireMutualAuthentication=1, RequireIntegrity=1, RequirePrivacy=1')) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths [\\*\NETLOGON]'
    $mismatchCount++
}

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('\\*\SYSVOL', $null, 'DoNotExpandEnvironmentNames') }
$kind = $null
if ($null -ne $current) { $kind = $key.GetValueKind('\\*\SYSVOL') }
if (-not ($current -is [string] -and $kind -ceq 'String' -and $current -ceq 'RequireMutualAuthentication=1, RequireIntegrity=1, RequirePrivacy=1')) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths [\\*\SYSVOL]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths' -Name '\\*\NETLOGON' -Value 'RequireMutualAuthentication=1, RequireIntegrity=1, RequirePrivacy=1' -PropertyType String -Force | Out-Null
if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Networkprovider\Hardenedpaths' -Name '\\*\SYSVOL' -Value 'RequireMutualAuthentication=1, RequireIntegrity=1, RequirePrivacy=1' -PropertyType String -Force | Out-Null
exit 0
